#!/bin/bash
# /workspace/recon/dump.sh OFFSET
# Dumps the exact intermediate Paths64 values of /workspace/dataset/test7_executable
# for a given integer 'offset' argv[1], using gdb breakpoints.
#
# Output format (one record per line):
#   OFFSET <n>
#   STDOUT <text printed by the program>
#   SECTION <NAME>
#   NPATHS <k>
#   PATH <index> <npts> x0,y0 x1,y1 ...
#   CALL ...            (call trace / counters)
#   COUNTS addpaths=<a> exec64=<e>
#
# Sections, in emission order:
#   INTERSECT_IN_SUBJ, INTERSECT_IN_CLIP, INTERSECT_OUT, OFFSET_RAW, OFFSET_OUT
set -u
BIN=/workspace/dataset/test7_executable
GDB=/opt/compiler/gcc-12/bin/gdb
OFF="${1:-10}"
GDBSCRIPT="${GDBSCRIPT:-/workspace/recon/dump.gdb}"

echo "OFFSET $OFF"
SO=$("$BIN" "$OFF" 2>/dev/null); RC=$?
echo "STDOUT $SO"
echo "EXITCODE $RC"

cd "$(dirname $BIN)"
"$GDB" -q -batch -x "$GDBSCRIPT" --args "$BIN" "$OFF" 2>/dev/null \
 | grep -E '^(SECTION|NPATHS|PATH|CALL|COUNTS) '
SH
chmod +x /workspace/recon/dump.sh
cat > /workspace/recon/shoelace.pl <<'PL'
#!/usr/bin/perl
# shoelace.pl : reads dump.sh output on stdin, computes signed area (shoelace/2)
# of each PATH in each SECTION, and compares SECTION OFFSET_OUT path 0 against STDOUT.
use strict; use warnings;
my ($off,$stdout,$sec)=("","","");
my %area; my %npts; my %npaths;
sub sarea {
  my @p=@_; my $n=@p; return 0 if $n<3;
  # Clipper2 Area(): sum over i of (p[i].y + p[i+1].y) * (p[i].x - p[i+1].x) * 0.5
  # equivalent magnitude to standard shoelace; we use the standard cross form
  my $s=0.0;
  for my $i (0..$n-1) { my $j=($i+1)%$n;
    $s += $p[$i][0]*$p[$j][1] - $p[$j][0]*$p[$i][1]; }
  return $s/2.0;
}
my @records;
while (my $l=<STDIN>) {
  chomp $l;
  if ($l=~/^OFFSET (\S+)/) { $off=$1; %area=(); %npts=(); %npaths=(); next; }
  if ($l=~/^STDOUT (.*)$/) { $stdout=$1; next; }
  if ($l=~/^SECTION (\S+)/) { $sec=$1; next; }
  if ($l=~/^NPATHS (\d+)/) { $npaths{$sec}=$1; next; }
  if ($l=~/^PATH (\d+) (\d+)\s*(.*)$/) {
    my ($idx,$n,$rest)=($1,$2,$3);
    my @p = map { [split /,/,$_] } split /\s+/, $rest;
    $area{"$sec.$idx"} = sarea(@p);
    $npts{"$sec.$idx"} = scalar(@p);
    next;
  }
}
for my $k (sort keys %area) { printf "AREA %s %s npts=%d signed=%.6f\n",$off,$k,$npts{$k},$area{$k}; }
# compare
if (exists $area{"OFFSET_OUT.0"}) {
  my $a=abs($area{"OFFSET_OUT.0"});
  # emulate ostream<<double default precision 6 significant digits
  my $fmt=sprintf("%.6g",$a);
  $fmt =~ s/e\+0*(\d\d+)/e+$1/; $fmt =~ s/e-0*(\d\d+)/e-$1/;
  my $ok = ($fmt eq $stdout) ? "MATCH":"MISMATCH";
  printf "CHECK %s stdout=%s shoelace=%s %s\n",$off,$stdout,$fmt,$ok;
} else {
  my $ok = ($stdout eq "0") ? "MATCH(empty)":"MISMATCH(empty)";
  printf "CHECK %s stdout=%s shoelace=<none> %s\n",$off,$stdout,$ok;
}
PL
chmod +x /workspace/recon/shoelace.pl
/workspace/recon/dump.sh 10 | tee /workspace/scratch/o10.txt | head -5; echo "..."; /workspace/recon/shoelace.pl < /workspace/scratch/o10.txt

cd /workspace/recon && cat > analyze.pl <<'PL'
#!/usr/bin/perl
use strict; use warnings;
my ($off,$stdout,$sec,$rc);
my (%paths,%raw,%out,%order);
my @offs;
my %db;
open(F,"<","/workspace/recon/ground_truth.txt") or die;
my $cur;
while (my $l=<F>) {
  chomp $l;
  if ($l=~/^OFFSET (\S+)/) { $off=$1; push @offs,$off; $db{$off}={sec=>{},order=>[]}; $cur=$db{$off}; next; }
  if ($l=~/^STDOUT (.*)$/) { $cur->{stdout}=$1; next; }
  if ($l=~/^EXITCODE (\d+)/) { $cur->{rc}=$1; next; }
  if ($l=~/^SECTION (\S+)/) { $sec=$1; push @{$cur->{order}},$sec; $cur->{sec}{$sec}=[]; next; }
  if ($l=~/^NPATHS (\d+)/) { $cur->{np}{$sec}=$1; next; }
  if ($l=~/^PATH (\d+) (\d+)\s*(.*)$/) {
    my @p = map { [split /,/,$_] } split /\s+/, $3;
    push @{$cur->{sec}{$sec}}, \@p; next; }
  if ($l=~/^COUNTS addpaths=(\d+) exec64=(\d+)/) { $cur->{ap}=$1; $cur->{ex}=$2; next; }
}
close F;
sub sa { my @p=@_; my $n=@p; return 0 if $n<3; my $s=0;
  for my $i (0..$n-1){my $j=($i+1)%$n; $s+=$p[$i][0]*$p[$j][1]-$p[$j][0]*$p[$i][1];} return $s/2; }
sub ptstr { my $p=shift; return join(" ",map {"$_->[0],$_->[1]"} @$p); }
# remove duplicate + collinear points (cyclic), keep order
sub clean {
  my @p=@_;
  # dedup consecutive (cyclic)
  my @q;
  for my $i (0..$#p) { my $j=($i+1)%scalar(@p);
    next if ($p[$i][0]==$p[$j][0] && $p[$i][1]==$p[$j][1]);
    push @q,$p[$i]; }
  return @q if @q<3;
  my @r; my $n=@q;
  for my $i (0..$n-1) {
    my $a=$q[($i-1+$n)%$n]; my $b=$q[$i]; my $c=$q[($i+1)%$n];
    my $cr=($b->[0]-$a->[0])*($c->[1]-$b->[1])-($b->[1]-$a->[1])*($c->[0]-$b->[0]);
    push @r,$b if $cr!=0;
  }
  return @r;
}
sub is_rot_of { # is @$A a cyclic rotation of @$B ?
  my ($A,$B)=@_;
  return (-1) if scalar(@$A)!=scalar(@$B) || !@$A;
  my $n=scalar(@$A);
  OUTER: for my $s (0..$n-1) {
    for my $i (0..$n-1) {
      my $bi=($s+$i)%$n;
      next OUTER if ($A->[$i][0]!=$B->[$bi][0] || $A->[$i][1]!=$B->[$bi][1]);
    }
    return $s;
  }
  return -1;
}
printf "%-7s %-10s %-3s %-3s %-5s %-14s %-5s %-14s %-6s %s\n","offset","stdout","ap","ex","rawN","rawArea","outN","out0Area","#out","rot/clean";
my @multi; my @notclean; my %isec;
for my $o (@offs) {
  my $d=$db{$o};
  my $rawp = $d->{sec}{OFFSET_RAW} // [];
  my $outp = $d->{sec}{OFFSET_OUT} // [];
  my $nraw = $d->{np}{OFFSET_RAW} // 0;
  my $nout = $d->{np}{OFFSET_OUT} // 0;
  my $rawA = @$rawp ? sa(@{$rawp->[0]}) : 0;
  my $outA = @$outp ? sa(@{$outp->[0]}) : 0;
  my $rn = @$rawp ? scalar(@{$rawp->[0]}) : 0;
  my $on = @$outp ? scalar(@{$outp->[0]}) : 0;
  my $note="";
  if ($nout>1) { push @multi,$o; }
  if (@$rawp && @$outp) {
    my @cl = clean(@{$rawp->[0]});
    my $r = is_rot_of($outp->[0], \@cl);
    if ($r>=0) { $note="ROT$r-of-clean(raw)"; }
    else { $note="DIFFERS"; push @notclean,$o; }
  } elsif (!@$outp) { $note="EMPTY_OUT"; }
  my $ip = $d->{sec}{INTERSECT_OUT};
  $isec{ptstr($ip->[0])}++ if $ip && @$ip;
  printf "%-7s %-10s %-3s %-3s %-5s %-14.4f %-5s %-14.4f %-6s %s\n",
    $o,$d->{stdout},$d->{ap},$d->{ex},$rn,$rawA,$on,$outA,$nout,$note;
}
print "\nMULTI-PATH OFFSET_OUT offsets: ", (@multi? join(",",@multi):"(none)"), "\n";
print "OFFSET_OUT[0] NOT rotation-of-clean(RAW[0]): ", (@notclean? join(",",@notclean):"(none)"), "\n";
print "\nDistinct INTERSECT_OUT path0 across all offsets:\n";
for my $k (sort keys %isec) { print "  [$k] x$isec{$k}\n"; }
PL
chmod +x analyze.pl && ./analyze.pl > /workspace/recon/analysis.txt; head -80 /workspace/recon/analysis.txt

cd /workspace/recon && perl -ne '
  if (/^OFFSET (\S+)/){$o=$1}
