  if (/^PATH 0 (\d+)\s*(.*)/ && ($s eq "OFFSET_RAW" || $s eq "OFFSET_OUT")){ printf "%-5s %-11s n=%-3d %s\n",$o,$s,$1,$2 }
' ground_truth.txt | awk '$1>=-45 && $1<=6'
